// Business Review — employee-portal scope resolution.
//
// Answers one question: for this signed-in viewer, WHICH part of the review may they see?
// Everything here is read-only.
//
// THE SEAT MAP IS READ LIVE. It used to be read from a committed snapshot,
// `data/access-map.json`, regenerated by hand from production. On 2026-09-12 the owner reported
// district managers being told "Not available for your role", and the snapshot was the whole
// cause: generated 2026-07-30, it named 16 DMs while production had 19 occupied DM seats, so
// SEVEN serving district managers — Samaa Shalaby, Mahmoud Eldaly and Weaam Mahmoud on Anti
// Infective, Mohamed Eleiwa, Ahmed Elsayed, Osama Mohamed and Mohamed Ramadan Khalaf on Pedia —
// were refused a module they are entitled to. Nothing was broken in the code: the file had simply
// aged past the Delta (3) move, the Upper Egypt split and six weeks of hiring.
//
// Regenerating it would have fixed that morning and re-broken on the next hire, silently, with the
// same symptom and no alarm — so the snapshot is gone from the request path. The org tree answers
// now, at the moment the viewer asks.
//
// Design constraints, each of them learned from a real defect in this repo:
//
//  - Scope comes from the SEAT MAP, never a region label. PR #1479: six live areas sit in
//    an operational region different from their geographic one, and region-label scoping
//    hid 1,194 of one DM's own sales rows.
//  - A Regional Manager gets the DM seats under their RSM node — the full set, not one
//    level. PR #1486: resolving a HIERARCHY scope with a one-level manager check made an
//    RM see their DSMs but none of the reps beneath them, so a semester rolled up to
//    "0.0%" and EGP 0 payout while the region was actually near 105% — wrong and silent.
//    On Pedia today that node carries three of the line's eight DM seats; the other five hang
//    off the NSM. Reading the PATH rather than the parent is what keeps that honest.
//  - Scope is applied BEFORE any truncation or ranking. PR #1487: truncating company-wide
//    first and filtering after silently emptied a scoped viewer's list.
//  - Every failure path returns NO access, never a wider one.
//  - The SESSION role decides which kind of scope is sought; the ORG TREE decides how far it
//    reaches. Neither is taken from client input, and a role with no seat is refused rather than
//    widened — the safe direction when the two disagree is "no".
//
// Two different timeframes meet here and are deliberately not merged: the numbers are the history
// of whatever window was picked, while access is decided by who sits where today. That is why this
// file reads the live tree and the canonical engine does not — a rep who left in March must still
// place correctly for January, and a DM appointed yesterday must still be able to open the page.
//
// The pure half (`resolveReviewPortalScopeFromOrg`) takes an already-loaded snapshot so every
// viewer shape can be asserted without a database. `loadReviewPortalScope` is the thin loader the
// page calls.

import { getSupabaseAdmin } from "@/lib/supabase/server";
import type { ReviewLine } from "./canonical";
import type { AreaSummary, DmSummary, ReviewDataset } from "./types";

/** Roles that see all three lines consolidated. */
const COMPANY_ROLES = new Set(["Super Admin", "CEO", "SFE Manager", "Marketing Manager"]);
/** Roles that see their own whole line. */
const WHOLE_LINE_ROLES = new Set(["National Sales Manager", "Group Product Manager", "Product Manager"]);

/** `au_v_org_tree.line_code` → the review's own line key. */
const LINE_BY_ORG_CODE: Record<string, ReviewLine> = {
  pedia: "pedia",
  cns: "cns",
  anti_infective: "anti",
};
/** `lines.name` (the employee record's line) → the review's own line key. */
const LINE_BY_DB_NAME: Record<string, ReviewLine> = {
  Pedia: "pedia",
  CNS: "cns",
  "Anti Infective": "anti",
  "Anti-Infective": "anti",
};
const LINE_LABEL: Record<ReviewLine, string> = {
  pedia: "Pedia",
  cns: "CNS",
  anti: "Anti-Infective",
};

/** Same normalisation the rest of Phoenix uses for HR_ID comparison — never compare raw. */
function hrKey(value: string | null | undefined): string {
  return String(value ?? "").trim().toUpperCase();
}

export type OrgSeat = {
  seatTier: "DM" | "RSM";
  seatId: string;
  lineCode: string;
  occupantHrId: string | null;
  /** Root-first ancestor chain, the seat itself last. */
  path: string[];
};

/** Everything the resolver needs, loaded once per request. */
export type ReviewOrgSnapshot = {
  seats: OrgSeat[];
  /** HR id (upper-cased) → the line name on their employee record, for the whole-line roles. */
  lineNameByHrId: Record<string, string | null>;
  /** When this snapshot was read. Live resolution, so: now. */
  readAt: string;
};

export type ReviewPortalScope =
  | { kind: "company"; viewerName: string; label: string }
  | { kind: "line"; line: ReviewLine; viewerName: string; label: string }
  | {
      kind: "seats";
      line: ReviewLine;
      /** Exact DM seats this viewer may see. Already the post-scope set. */
      dmSeatIds: string[];
      viewerName: string;
      label: string;
    }
  | { kind: "none"; reason: string };

/**
 * Resolve what this viewer may see, against an already-loaded org snapshot.
 *
 * `sessionRole` must be the role from the live AccessContext, never from client input. The viewer's
 * NAME is only ever used for display, so it is passed in rather than looked up — one fewer reason
 * for this function to need a database.
 */
export function resolveReviewPortalScopeFromOrg(
  input: { hrId: string | null; sessionRole: string; viewerName?: string | null },
  org: ReviewOrgSnapshot,
): ReviewPortalScope {
  const key = hrKey(input.hrId);
  if (!key) return { kind: "none", reason: "No HR ID on the session." };

  const role = input.sessionRole;
  const viewerName = input.viewerName?.trim() || input.hrId || "";

  if (COMPANY_ROLES.has(role)) {
    return { kind: "company", viewerName, label: `${role} · all three lines` };
  }

  if (WHOLE_LINE_ROLES.has(role)) {
    const line = LINE_BY_DB_NAME[String(org.lineNameByHrId[key] ?? "").trim()];
    if (!line) {
      return {
        kind: "none",
        reason: "No line is recorded against your employee record, so a whole-line scope cannot be granted.",
      };
    }
    return { kind: "line", line, viewerName, label: `${role} · ${LINE_LABEL[line]} line` };
  }

  // ---- seat-level scopes: a District Manager's own seat, a Regional Manager's whole subtree ----
  //
  // Both are resolved from OCCUPANCY, so a manager appointed this morning resolves this morning and
  // one who left yesterday resolves to nothing. That is the whole reason the snapshot was retired.
  if (role === "District Manager") {
    const seat = org.seats.find((s) => s.seatTier === "DM" && hrKey(s.occupantHrId) === key);
    if (!seat) {
      return {
        kind: "none",
        reason:
          "You hold the District Manager role but occupy no district seat in the organogram, so no " +
          "territory can be resolved. This is an organogram gap rather than a decision about you — " +
          "please report it.",
      };
    }
    const line = LINE_BY_ORG_CODE[seat.lineCode];
    if (!line) {
      return { kind: "none", reason: "Your district sits on a line the Business Review does not cover." };
    }
    return {
      kind: "seats",
      line,
      dmSeatIds: [seat.seatId],
      viewerName,
      label: `${role} · own district`,
    };
  }

  if (role === "Regional Manager") {
    const rsm = org.seats.find((s) => s.seatTier === "RSM" && hrKey(s.occupantHrId) === key);
    if (!rsm) {
      return {
        kind: "none",
        reason:
          "You hold the Regional Manager role but occupy no regional seat in the organogram, so no " +
          "districts can be resolved. This is an organogram gap rather than a decision about you — " +
          "please report it.",
      };
    }
    const line = LINE_BY_ORG_CODE[rsm.lineCode];
    if (!line) {
      return { kind: "none", reason: "Your region sits on a line the Business Review does not cover." };
    }
    // The PATH, not the parent: a DM seat two levels below an RSM node is still that RM's, and
    // resolving one level is exactly the PR #1486 defect. The seat itself is excluded — an RSM seat
    // is never its own district.
    const dmSeatIds = org.seats
      .filter(
        (s) =>
          s.seatTier === "DM" &&
          s.lineCode === rsm.lineCode &&
          s.seatId !== rsm.seatId &&
          s.path.includes(rsm.seatId),
      )
      .map((s) => s.seatId);
    if (!dmSeatIds.length) {
      return {
        kind: "none",
        reason: "No district seats sit under your regional seat in the organogram, so no territory can be resolved.",
      };
    }
    return {
      kind: "seats",
      line,
      dmSeatIds,
      viewerName,
      label: `${role} · ${dmSeatIds.length} districts`,
    };
  }

  return {
    kind: "none",
    reason:
      "Your Phoenix role does not carry a Business Review scope. Medical Representatives have no " +
      "access to this module by design.",
  };
}

/**
 * Read the live seat map. One query for the seats, one for the whole-line roles' line name — and
 * the second is skipped entirely for every role that does not need it.
 *
 * A failed read returns NO snapshot rather than an empty one, because an empty snapshot and a
 * broken query look identical to the resolver and the first would silently deny every manager.
 */
export async function loadReviewOrgSnapshot(options?: { needsLineName?: string | null }): Promise<ReviewOrgSnapshot> {
  const db = getSupabaseAdmin();
  const seatRes = await db
    .from("au_v_org_tree")
    .select("seat_tier,seat_id,line_code,occupant_hr_id,path")
    .in("seat_tier", ["DM", "RSM"]);
  if (seatRes.error) throw new Error(`Business Review: could not read the organogram — ${seatRes.error.message}`);

  const seats: OrgSeat[] = (seatRes.data ?? []).map((r) => ({
    seatTier: r.seat_tier as "DM" | "RSM",
    seatId: String(r.seat_id),
    lineCode: String(r.line_code ?? ""),
    occupantHrId: r.occupant_hr_id ?? null,
    // `path` is a text[] in the view. Normalised here so the resolver never has to care.
    path: Array.isArray(r.path) ? r.path.map((p: unknown) => String(p)) : [],
  }));

  const lineNameByHrId: Record<string, string | null> = {};
  const raw = String(options?.needsLineName ?? "").trim();
  const wanted = hrKey(raw);
  if (wanted) {
    // `in` on the three spellings rather than `ilike`: HR ids reach this code from three systems in
    // mixed case, and a pattern match would give `_` and `%` meaning inside an identifier.
    const empRes = await db
      .from("employees")
      .select("hr_id,line_id")
      .in("hr_id", Array.from(new Set([raw, raw.toUpperCase(), raw.toLowerCase()])));
    if (empRes.error) {
      throw new Error(`Business Review: could not read your employee record — ${empRes.error.message}`);
    }
    const lineId = (empRes.data ?? []).find((r) => hrKey(r.hr_id) === wanted)?.line_id ?? null;
    if (lineId != null) {
      // Resolved in two hops rather than an embedded join: `employees.line_name` is NULL for
      // everyone, and an embed would bind this read to a named FK relationship it does not need.
      const lineRes = await db.from("lines").select("id,name").eq("id", lineId).maybeSingle();
      if (lineRes.error) {
        throw new Error(`Business Review: could not read your line — ${lineRes.error.message}`);
      }
      lineNameByHrId[wanted] = lineRes.data?.name ?? null;
    } else {
      lineNameByHrId[wanted] = null;
    }
  }

  return { seats, lineNameByHrId, readAt: new Date().toISOString() };
}

/**
 * What the page calls: resolve this viewer's scope against the organogram as it stands right now.
 */
export async function loadReviewPortalScope(input: {
  hrId: string | null;
  sessionRole: string;
  viewerName?: string | null;
}): Promise<{ scope: ReviewPortalScope; resolvedAt: string }> {
  const needsLineName = WHOLE_LINE_ROLES.has(input.sessionRole) ? input.hrId : null;
  const org = await loadReviewOrgSnapshot({ needsLineName });
  return { scope: resolveReviewPortalScopeFromOrg(input, org), resolvedAt: org.readAt };
}

/**
 * Areas + DM rows filtered to a seat-level scope.
 *
 * Filtering happens here, before any ranking or truncation (PR #1487). The seat id is the
 * canonical engine's own attribution key, so this is an exact match rather than a name
 * reconciliation — an area either was attributed to that seat during the window or it was not.
 */
export function applySeatScope(ds: ReviewDataset, dmSeatIds: readonly string[]): { areas: AreaSummary[]; dms: DmSummary[] } {
  const keep = new Set(dmSeatIds);
  return {
    areas: ds.areas.filter((a) => a.dmSeatId && keep.has(a.dmSeatId)),
    dms: ds.dms.filter((d) => d.dmSeatId && keep.has(d.dmSeatId)),
  };
}
